import java.io.*;import com.koios.client.definition.*;import com.koios.client.cache.Decompressor;import com.koios.client.stream.StreamLoader;public class FloorProbe {public static void main(String[] args)throws Exception{try(RandomAccessFile d=new RandomAccessFile("../koios-cache/main_file_cache.dat","r");RandomAccessFile i=new RandomAccessFile("../koios-cache/main_file_cache.idx0","r")){FloorDefinition.unpackConfig(new StreamLoader(new Decompressor(d,i,1).decompress(2)));}for(int id=1;id<=FloorDefinition.cache.length&&id<=255;id++){FloorDefinition f=FloorDefinition.cache[id-1];if(id==82||id==162||id==172||Math.abs(f.anInt390-0x41583A)<10000)System.out.println(id+" rgb="+Integer.toHexString(f.anInt390)+" hue="+f.anInt394+" sat="+f.anInt395+" light="+f.anInt396+" weighted="+f.anInt397+" multiplier="+f.anInt398+" renderHue="+(f.anInt398==0?999:256*f.anInt397/f.anInt398));}}}
